{"command":"python3 - <<'PY'
from subprocess import check_output
for n in range(1,21):
    with open(f'/tmp/lines{n}.txt','w') as f:
        f.write('\n'.join(f'line{i}' for i in range(1,n+1)))
    orig = check_output(['./executable', f'/tmp/lines{n}.txt']).decode('utf-8')
    toks = orig.strip().split('\n')
    last_chars = []
    for t in toks:
        if t:
            last_chars.append((t, [hex(ord(c)) for c in t]))
    print(n)
    for t,chars in last_chars:
        print('  token:',t,'codes',chars)
    print('---')
PY"}

